const view=document.querySelector('#view'), overlay=document.querySelector('#overlay-root');
const defaultState={page:'intro',day:1,stage:0,checked:false,reply:false,replyChoice:0,stress:8,trust:70,clues:0,tab:'微信',playerId:'',avatar:0,profileDraft:'',theme:'dark',navStack:[],messageSpeed:2200,gameClockMinute:1216,storyRunId:'',storyCaptured:{},contactRemarks:{},seenAnnouncement:false,yutongStage:0,groupReadStage:0,neighborReadStage:0,groupReactionReady:false,groupReactionPending:false,groupReactionRead:false,dayOneUnlocked:false,dayOneBodySeen:false,dayOneTasks:{},dayOneChoice:null,dayOneAsked:false,dayOneInquiryStep:0,dayOneInquiryTextChoice:0,dayOneInquirySentAt:0,dayOneMimiStep:0,dayOneMimiChoice:0,dayOneMimiSentAt:0,dayOneFlowRevision:2,dayOneSlept:false,dayOneFinished:false,nightChoice:null,nightStep:0,nightCluesSeen:{},nightCurrentClue:null,storyEnding:null,nightAlertRead:false,nightPhase:'idle',nightLinMessage:0,nightLinIssuedAt:0,nightLinOpenedAt:0,nightLinAsk:0,nightLinAskAt:0,nightRepairStatus:'',appRevealPending:false,nightPlateChecked:false,nightRepairAt:0,nightDoorStep:0,nightMistake:'',investigation:{},stamina:82,satiety:58,mood:72};
let storedState={};
try{storedState=JSON.parse(localStorage.getItem('resident_register_v1')||'{}')||{}}catch(e){}
const state={...defaultState,...storedState,page:'intro',navStack:[],phoneActivated:false,playerId:'',avatar:0,profileDraft:''};
let hasSavedTheme=false;try{hasSavedTheme=!!localStorage.getItem('resident_theme_set_v8')}catch(e){}
state.theme=hasSavedTheme? (state.theme==='light'?'light':'dark') : 'dark';
state.messageSpeed=([700,1600,3000].includes(state.messageSpeed)?{700:1000,1600:2200,3000:3600}[state.messageSpeed]:state.messageSpeed); state.messageSpeed=[1000,2200,3600].includes(state.messageSpeed)?state.messageSpeed:2200;
let narrativeTimer=null, bannerTimer=null, neighborTimer=null, groupReactionTimer=null;
const SAVE_KEY='resident_registration_save_v2';
function readSave(){try{const obj=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');return obj&&typeof obj==='object'&&obj.playerId&&validId(obj.playerId)?obj:null}catch(e){return null}}
function hasContinueSave(){return !!readSave()}
function persistSave(){if(!state.playerId||!validId(state.playerId)||state.page==='intro'||state.page==='warning'||state.page==='profile')return;try{localStorage.setItem(SAVE_KEY,JSON.stringify({...state,navStack:Array.isArray(state.navStack)?state.navStack.slice(-30):[]}))}catch(e){}}

function cancelNarrative(){if(narrativeTimer){clearTimeout(narrativeTimer);narrativeTimer=null}if(neighborTimer){clearTimeout(neighborTimer);neighborTimer=null}if(groupReactionTimer){clearTimeout(groupReactionTimer);groupReactionTimer=null}}
function groupMessageCount(){return Math.max(0,Math.min(7,Number(state.stage)||0))+(state.groupReactionReady?1:0)}
function neighborMessageCount(){
 const s=Number(state.yutongStage)||0;
 let c=0;
 if(s>=1)c++;
 if(s>=2)c++;
 if(s>=4)c++;
 if(s>=5)c++;
 return c;
}
function unreadGroupCount(){return Math.max(0,groupMessageCount()-(Number(state.groupReadStage)||0))}
function unreadNeighborCount(){return Math.max(0,neighborMessageCount()-(Number(state.neighborReadStage)||0))}
function totalWechatUnread(){return unreadGroupCount()+unreadNeighborCount()}
function markGroupRead(){state.groupReadStage=groupMessageCount();store()}
function markNeighborRead(){state.neighborReadStage=neighborMessageCount();store()}
function isViewingTarget(target){
 if(target==='chat')return ['chat','members','rules'].includes(state.page);
 if(target==='neighbor')return state.page==='neighbor';
 return state.page===target;
}
function advanceGroupMessage(){
 if(!state.phoneActivated)return;
 if(state.stage>=7)return;
 if(state.stage===3 && !state.seenAnnouncement)return;
 if(state.stage===6 && !state.checked)return;
 state.stage=Math.min(7,(Number(state.stage)||0)+1);
 if(state.page==='chat')state.groupReadStage=groupMessageCount();
 store();
 if(!isViewingTarget('chat'))banner(state.stage===1?T('公告标题'):T('群聊'+state.stage+'正文'), state.stage===1?E('业主群名称'):T('群聊'+state.stage+'发言人'),'chat');
 if(state.page!=='rules'&&state.page!=='members')render();
 scheduleGroupNarrative();
}
function scheduleGroupNarrative(){
 if(narrativeTimer){clearTimeout(narrativeTimer);narrativeTimer=null}
 if(!state.phoneActivated || state.reply || state.stage>=7)return;
 if(state.stage===3 && !state.seenAnnouncement)return;
 if(state.stage===6 && !state.checked)return;
 const ms=state.stage===0?Math.max(Number(state.messageSpeed)||2200, (Number(state.phoneStartAt)||Date.now())+3600-Date.now()):Math.max(700,Number(state.messageSpeed)||2200);
 narrativeTimer=setTimeout(advanceGroupMessage,ms);
}
function scheduleGroupReaction(){
 if(groupReactionTimer){clearTimeout(groupReactionTimer);groupReactionTimer=null}
 if(!state.phoneActivated||!state.groupReactionPending||state.groupReactionReady||![1,2].includes(state.replyChoice))return;
 groupReactionTimer=setTimeout(()=>{
   groupReactionTimer=null;
   if(!state.groupReactionPending||state.groupReactionReady)return;
   state.groupReactionReady=true;state.groupReactionPending=false;
   if(state.page==='chat')state.groupReadStage=groupMessageCount();
   store();
   if(!isViewingTarget('chat'))banner(T('群聊回复反馈'+state.replyChoice+'正文'),T('群聊回复反馈'+state.replyChoice+'发言人'),'chat');
   if(state.page!=='rules'&&state.page!=='members')render();
 },Math.max(900,Number(state.messageSpeed)||2200));
}
function advanceNeighborMessage(){
 if(!state.phoneActivated)return;
 const current=Number(state.yutongStage)||0;
 if(![1,3,4].includes(current))return;
 state.yutongStage=current+1;
 if(state.yutongStage===5 && typeof unlockDayOne==='function')unlockDayOne();
 if(state.page==='neighbor')state.neighborReadStage=neighborMessageCount();
 let key=state.yutongStage===2?'王雨桐新消息2':state.yutongStage===4?'王雨桐后续消息1':'王雨桐后续消息2';
 store();
 if(!isViewingTarget('neighbor'))banner(T(key),'王雨桐','neighbor');
 if(state.page!=='rules'&&state.page!=='members')render();
 scheduleNeighborNarrative();
}
function scheduleNeighborNarrative(){
 if(neighborTimer){clearTimeout(neighborTimer);neighborTimer=null}
 if(!state.phoneActivated || ![1,3,4].includes(Number(state.yutongStage)||0))return;
 neighborTimer=setTimeout(advanceNeighborMessage, Math.max(700,Number(state.messageSpeed)||2200));
}
// 单一游戏时间线：时间只前进，不因跳转页面而倒退。
function rrClockMinute(t){const a=String(t).split(':').map(Number);return a[0]*60+a[1]}
function rrClockText(min){const d=((min%1440)+1440)%1440;return String(Math.floor(d/60)).padStart(2,'0')+':'+String(d%60).padStart(2,'0')}
function rrTargetMinute(){
 let t=20*60+16;
 if(state.stage>=4)t=Math.max(t,20*60+18);
 if(state.groupReactionReady||state.yutongStage>=1)t=Math.max(t,20*60+20);
 if(state.dayOneUnlocked)t=Math.max(t,20*60+32);
 if(state.dayOneAsked)t=Math.max(t,20*60+44);
 if(state.dayOneMimiStep)t=Math.max(t,20*60+48);
 if(state.dayOneMimiStep>=4 || state.page==='day1-night')t=Math.max(t,23*60+12);
 if(state.nightChoice)t=Math.max(t,23*60+12);
 if(state.nightChoice==='browse')t=Math.max(t,23*60+46);
 if(state.nightLinMessage>=1)t=Math.max(t,23*60+46);
 if(state.nightLinMessage===2)t=Math.max(t,23*60+49);
 if(state.nightRepairStatus==='pending')t=Math.max(t,23*60+51);
 if(state.nightRepairStatus==='accepted')t=Math.max(t,23*60+55);
 if(state.nightDoorStep>=1)t=Math.max(t,23*60+58);
 if(state.nightDoorStep>=2)t=Math.max(t,24*60+3);
 if(state.nightDoorStep>=3 || state.nightRepairStatus==='fixed')t=Math.max(t,24*60+7);
 if(state.nightDoorStep>=4 || state.storyEnding)t=Math.max(t,24*60+12);
 return t;
}
function fictionalClock(){state.gameClockMinute=Math.max(Number(state.gameClockMinute)||1216,rrTargetMinute());return rrClockText(state.gameClockMinute)}
function rrTimeAt(limit){const actual=Math.max(Number(state.gameClockMinute)||1216,rrTargetMinute());return rrClockText(Math.min(rrClockMinute(limit),actual))}

function banner(message,from='微信',target='chat'){
 if(!state.phoneActivated || ['intro','warning','profile','chapter','scene'].includes(state.page) || isViewingTarget(target))return;
 if(typeof SoundFX!=='undefined')SoundFX.play('message');
 const old=document.getElementById('incoming-banner');if(old)old.remove();
 const b=document.createElement('button');b.id='incoming-banner';b.className='incoming-banner';
 const summary=String(message||'').replace(/\s+/g,' ').slice(0,64);
 b.innerHTML='<b><span>'+clean('微信 · '+from)+'</span><span class="banner-time">'+clean(fictionalClock())+'</span></b><span>'+clean(summary)+'</span>';
 b.onclick=()=>{b.remove();if(target==='direct-chat')state.dmPerson='小林';go(target)};
 document.querySelector('.phone-screen').appendChild(b);
 clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>{if(b.isConnected)b.remove()},Math.max(5200,Math.min(9000,(Number(state.messageSpeed)||1600)*3.2)));
}
