state.profileDraft='';
const store=()=>{try{localStorage.setItem('resident_register_v1',JSON.stringify(state))}catch(e){}persistSave();if(typeof rememberStoryMilestones==='function')rememberStoryMilestones()};

// 所有可编辑剧情文案都放在同目录的 story.txt。
const story=Object.create(null);
function parseStory(source){
  const found=Object.create(null);let key=null;let chunk=[];
  function save(){if(key!==null)found[key]=chunk.join('\n').trim()}
  for(const raw of source.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n')){
    const match=raw.trim().match(/^【(.+?)】$/);
    if(match){save();key=match[1].trim();chunk=[];continue}
    if(key!==null && !raw.trim().startsWith('#'))chunk.push(raw);
  }
  save();return found;
}
function T(key){return story[key]||''}
function E(key){return clean(T(key))}
function L(key){return E(key).replace(/\n/g,'<br>')}
function storyMsg(i,cls){return msg(T('群聊'+i+'发言人'),i===1?T('公告正文'):T('群聊'+i+'正文'),cls)}
function installStory(source){
  const parsed=parseStory(source);
  if(!parsed['游戏名称']||!parsed['公告正文'])throw new Error('story.txt 缺少游戏名称或公告正文');
  for(const key in story)delete story[key];
  Object.assign(story,parsed);
  document.title=T('游戏名称')+' · Day 1 互动预览';
  // 手机优先：桌面侧边信息不再显示。
  render();
  scheduleGroupNarrative();
  scheduleNeighborNarrative();
  scheduleGroupReaction();
}
function showStoryPicker(error){
  document.querySelector('#view').innerHTML=`<div class="cover-game warning"><div class="cover-supra">STORY FILE</div><h1 style="font-size:26px">加载剧情文字</h1><p>${location.protocol==='file:'?'浏览器不允许直接读取本地 TXT 文件。请选择game/data 文件夹中的 story.txt 文件。':'暂时无法自动读取 game/data/story.txt，请确认文件已经上传至 GitHub 仓库，或在此手动选择文件。'}</p><label class="primary" style="cursor:pointer;display:block;padding:14px 18px;border-radius:8px">选择 story.txt<input type="file" accept=".txt,text/plain" style="display:none" onchange="importStoryFile(this)"></label><small>${clean(String(error?.message||''))}</small></div>`;
}
async function importStoryFile(input){
  if(!input.files||!input.files.length)return;
  try{installStory(await input.files[0].text())}
  catch(e){showStoryPicker(e)}
}
async function loadStory(){
  try{
    const r=await fetch(new URL('game/data/story.txt',location.href),{cache:'no-store'});
    if(!r.ok)throw new Error('HTTP '+r.status);
    installStory(await r.text());
  }catch(e){if(typeof window.RESIDENT_OFFLINE_STORY==='string'){try{installStory(window.RESIDENT_OFFLINE_STORY);return}catch(_){} }showStoryPicker(e)}
}

const avatarMark=(slot,small=false)=>{
 const pal=[['#e9c7d1','#fff8fb'],['#a6d2c8','#f9fffe'],['#c6bfdf','#fffaff']][Math.max(0,Math.min(2,(Number(slot)||1)-1))];
 return `<svg class="avat-portrait ${small?'sm':'lg'}" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="玩家头像"><rect width="100" height="100" rx="16" fill="${pal[0]}"/><circle cx="50" cy="36" r="16" fill="${pal[1]}"/><path d="M20 92 C20 73 33 61 50 61 C67 61 80 73 80 92 V100 H20Z" fill="${pal[1]}"/></svg>`;
};
const validId=s=>{const chars=Array.from(String(s).trim());return chars.length>=1&&chars.length<=4&&chars.every(c=>/\p{Script=Han}/u.test(c))};

