function header(name,back){return `<div class="screen app-white"><header class="app-header"><button class="icon-btn" onclick="goBack()" aria-label="返回上一页">‹</button><h2>${name}</h2><div class="right-space"></div></header>`}
function msg(name,body,cls,mine=false){
  // All chat-avatar taps share the same WeChat profile & moments permissions as contacts.
  const personName=mine?'我':name;
  const iconHtml=personAvatar(personName);
  return `<div class="msg-row ${mine?'mine':''}"><button type="button" class="avatar-tap msg-avatar-btn" onclick="openPerson('${encodeURIComponent(personName)}')" aria-label="查看${clean(personName)}的资料">${iconHtml}</button><div class="msg-bubble-wrap">${mine||state.page!=='chat'?'':`<div class="msg-name">${clean(name)}</div>`}<div class="msg-bubble">${clean(body)}</div></div></div>`;
}
function chooseAvatar(i){
 state.avatar=i;store();
 document.querySelectorAll('.avatar-choice').forEach((btn,index)=>{
  btn.classList.toggle('selected',index+1===i);
  btn.setAttribute('aria-pressed',String(index+1===i));
 });
 validateProfile();
}
function updateProfile(){
 const input=document.querySelector('#profile-id');
 if(!input)return;
 state.profileDraft=input.value;
 validateProfile();
}
function validateProfile(){
 const field=document.querySelector('#profile-id');
 if(!field)return false;
 const id=field.value.trim();
 const count=Array.from(id).length;
 const okay=validId(id);
 const label=document.querySelector('#profile-tip');
 document.querySelector('#profile-count').textContent=`${count}/4`;
 label.classList.toggle('invalid',count>0&&!okay);
 label.textContent=count===0?'支持简体、繁体，最多 4 个汉字。':okay?'这个 ID 可以使用。':count>4?'ID 最多只能输入 4 个汉字。':'ID 只能使用中文汉字（支持繁体）。';
 document.querySelector('#profile-continue').disabled=!(okay&&state.avatar>=1&&state.avatar<=3);
 return okay;
}
function confirmProfile(){
 if(!validateProfile()){notify('请填写 1–4 个中文汉字的 ID');return}
 if(!state.avatar){notify('请先选择头像');return}
 state.playerId=document.querySelector('#profile-id').value.trim();
 state.profileDraft=state.playerId;
 store();go('chapter');
}
// The previous screen is recorded instead of hardcoding a return destination.
// This is important when the same announcement opens from chat, group info or the property app.
// Day 1 does not begin delivering messages until the player taps "查看手机".
function clearSave(){try{localStorage.removeItem(SAVE_KEY)}catch(e){}}
function startNewGame(){
 if(hasContinueSave()){
   document.querySelector('#overlay-root').innerHTML=`<div class="save-prompt"><div role="dialog" aria-modal="true"><h3>开始新游戏？</h3><p>将覆盖当前浏览器的游戏进度。确定后需要重新填写 ID 和选择头像。</p><button onclick="confirmNewGame()">确定开始</button><button onclick="closeSavePrompt()">取消</button></div></div>`;
 }else confirmNewGame();
}
function closeSavePrompt(){document.querySelector('#overlay-root').innerHTML=''}
function confirmNewGame(){
 cancelNarrative();clearTimeout(bannerTimer);document.getElementById('incoming-banner')?.remove();closeSavePrompt();
 const theme=state.theme,speed=state.messageSpeed;
 clearSave();Object.assign(state,defaultState,{theme,messageSpeed:speed,gameClockMinute:1216,navStack:[],page:'warning',profileDraft:'',playerId:'',avatar:0,phoneActivated:false,phoneStartAt:0,storyRunId:'run-'+Date.now()+'-'+Math.random().toString(36).slice(2),storyCaptured:{}});
 store();render();
}
function continueGame(){
 const snapshot=readSave();if(!snapshot){notify('没有可以继续的存档');render();return}
 cancelNarrative();clearTimeout(bannerTimer);document.getElementById('incoming-banner')?.remove();closeSavePrompt();
 const dest=['intro','warning','profile'].includes(snapshot.page)?'home':snapshot.page;
 Object.assign(state,defaultState,snapshot,{page:dest,navStack:Array.isArray(snapshot.navStack)?snapshot.navStack.slice(-30):[],theme:state.theme,profileDraft:'',phoneActivated:!!snapshot.phoneActivated});
 if(typeof migrateDayOneConversationSave==='function')migrateDayOneConversationSave(snapshot);
 if(state.nightChoice==='browse'&&!state.storyEnding&&['idle',''].includes(state.nightPhase||'idle')){state.nightPhase='waiting';state.nightStep=Date.now()+2300;state.nightLinMessage=0;state.nightLinOpenedAt=0;state.nightRepairStatus=''}
 if(!state.storyRunId)state.storyRunId='run-legacy-'+Date.now();if(!state.storyCaptured)state.storyCaptured={};
 if(!state.phoneActivated && !['chapter','scene'].includes(dest)){state.page='scene'}
 if(state.stage===0&&state.phoneActivated)state.phoneStartAt=Date.now();
 store();render();scheduleGroupNarrative();scheduleNeighborNarrative();scheduleGroupReaction();
}
function beginPhoneExperience(){
 cancelNarrative();
 clearTimeout(bannerTimer);
 const oldBanner=document.getElementById('incoming-banner');
 if(oldBanner)oldBanner.remove();
 Object.assign(state,{phoneActivated:true,phoneStartAt:Date.now(),gameClockMinute:1216,stage:0,checked:false,reply:false,replyChoice:0,seenAnnouncement:false,yutongStage:0,groupReadStage:0,neighborReadStage:0,groupReactionReady:false,groupReactionPending:false,groupReactionRead:false,clues:0,stress:8,trust:70,dayOneUnlocked:false,dayOneBodySeen:false,dayOneTasks:{},dayOneChoice:null,dayOneAsked:false,dayOneInquiryStep:0,dayOneInquiryTextChoice:0,dayOneInquirySentAt:0,dayOneMimiStep:0,dayOneMimiChoice:0,dayOneMimiSentAt:0,dayOneFlowRevision:2,dayOneSlept:false,dayOneFinished:false,nightChoice:null,nightStep:0,nightCluesSeen:{},nightCurrentClue:null,storyEnding:null,nightAlertRead:false,nightPhase:'idle',nightLinMessage:0,nightLinIssuedAt:0,nightLinOpenedAt:0,nightLinAsk:0,nightLinAskAt:0,nightRepairStatus:'',appRevealPending:false,nightPlateChecked:false,nightRepairAt:0,nightDoorStep:0,nightMistake:'',investigation:{},stamina:82,satiety:58,mood:72});
 store();
 go('home');
}
function go(p){
 const activeBanner=document.getElementById('incoming-banner');
 if(activeBanner && (p==='chat'||p==='neighbor'||p==='direct-chat'||p==='mimi-story')){activeBanner.remove();clearTimeout(bannerTimer)}
 if(state.page!==p){
  if(!Array.isArray(state.navStack))state.navStack=[];
  state.navStack.push(state.page);
  if(state.navStack.length>40)state.navStack.shift();
 }
 state.page=p;if(typeof nightOnNavigate==='function')nightOnNavigate(p);store();render();
 if(p==='chat')markGroupRead(); if(p==='neighbor')markNeighborRead(); if(typeof dayOneOnNavigate==='function')dayOneOnNavigate(p);scheduleGroupNarrative(); scheduleNeighborNarrative(); scheduleGroupReaction();
}
function goBack(){
 cancelNarrative();
 if(['chat','neighbor','direct-chat','mimi-story'].includes(state.page)){state.navStack=[];state.tab='微信';state.page='wechat';store();render();scheduleGroupNarrative();scheduleNeighborNarrative();scheduleGroupReaction();return;}
 const previous=(Array.isArray(state.navStack)?state.navStack:[]).pop();
 state.page=previous||'home';if(typeof dayOneSync==='function')dayOneSync(); if(state.page==='chat')markGroupRead(); if(state.page==='neighbor')markNeighborRead(); store();render(); scheduleGroupNarrative(); scheduleNeighborNarrative(); scheduleGroupReaction();
}
let appRevealTimer=null;
function rrShowNewAppOnHome(){
 if(!state.appRevealPending||state.page!=='home'||appRevealTimer)return;
 const screen=document.querySelector('.phone-screen');if(!screen)return;
 screen.classList.add('rr-app-blink');
 if(typeof SoundFX!=='undefined')SoundFX.play('anomaly');
 appRevealTimer=setTimeout(()=>{
  appRevealTimer=null;screen.classList.remove('rr-app-blink');
  if(state.page==='home'){state.appRevealPending=false;store();render();}
 },760);
}
function goHome(){if(typeof dayOneSync==='function')dayOneSync();state.navStack=[];state.page='home';store();render();rrShowNewAppOnHome();scheduleGroupNarrative();scheduleNeighborNarrative();scheduleGroupReaction()}
function setTheme(next){
 if(next!=='light'&&next!=='dark')return;
 state.theme=next;try{localStorage.setItem('resident_theme_set_v8','yes')}catch(e){}store();render();
}
function openApp(a){const pages={'微信':'wechat','相册':'gallery','电话':'phone','短信':'sms','备忘录':'notes','物业服务':'property','设置':'settings','身体状态':'body-status'};go(pages[a])}
function visibleClueCount(){return typeof nightInvestigationEntries==='function'?nightInvestigationEntries().length:(Number(state.clues)||0)}
function groupCount(){return T('群成员名单').split('\n').filter(Boolean).length}
function openAnnouncement(){state.seenAnnouncement=true;state.stage=Math.max(3,state.stage);if(typeof nightRecordEvidence==='function')nightRecordEvidence('notice');cancelNarrative();store();go('rules');scheduleGroupNarrative()}
function finishGroup(){state.reply=true;state.replyChoice=0;state.stage=7;state.yutongStage=1;state.groupReactionPending=false;store();render();if(!isViewingTarget('neighbor'))banner(T('王雨桐新消息1'),'王雨桐','neighbor');scheduleNeighborNarrative()}
function replyNeighbor(choice){state.yutongReply=choice;state.yutongStage=3;store();render();scheduleNeighborNarrative()}
function setSpeed(v){state.messageSpeed=v;state.speedHintSeen=true;store();render();scheduleGroupNarrative();scheduleNeighborNarrative();scheduleGroupReaction()}
function reply(choice){state.reply=true;state.replyChoice=choice;state.stage=7;state.yutongStage=1;state.groupReactionReady=false;state.groupReactionPending=[1,2].includes(choice);store();render();if(!isViewingTarget('neighbor'))banner(T('王雨桐新消息1'),'王雨桐','neighbor');scheduleNeighborNarrative();scheduleGroupReaction()}
function notify(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3000)}
function reset(){startNewGame()}
document.querySelector('#phone-screen').addEventListener('click',event=>{
 const control=event.target.closest('button');
 if(!control||control.classList.contains('rr-audio-switch')||control.closest('.rr-cg-scene'))return;
 if(!document.querySelector('#phone-screen').contains(control))return;
 SoundFX.play('confirm');
});
document.querySelector('#home-gesture').addEventListener('click',goHome);
loadStory();